fn rsplit(a: Vec<String>, sep: String, maxsplit: u8) -> Vec<Vec<String>> {
    let maxsplit = maxsplit as usize; // Convert u8 to usize for easier handling

    // Requires: a is a vector of strings, sep is a non-empty string, and maxsplit is non-negative.
    // Ensures: The result is a vector of vectors of strings, where each inner vector contains the parts
    // of the corresponding string in `a` split by `sep`, with at most `maxsplit` splits performed.
    // The order of parts in each inner vector is from left to right.
    // The total number of parts across all inner vectors is at least 1 and at most the length of the original string.
    // The function does not modify the input vector `a`.
    // The function maintains the invariant that the number of splits does not exceed `maxsplit`.
    // The function decreases the number of remaining splits with each iteration.
    a.into_iter()
        .map(|s| {
            if maxsplit == 0 {
                // If maxsplit is 0, return the original string as a single-element vector
                vec![s]
            } else {
                // Perform the right-split operation
                let mut parts = Vec::new();
                let mut remaining = s.as_str();
                let mut splits = 0;

                // Split from the right
                while let Some(pos) = remaining.rfind(&sep) {
                    // Ensure that we do not exceed the maximum number of splits
                    assert!(splits < maxsplit);
                    parts.push(remaining[pos + sep.len()..].to_string());
                    remaining = &remaining[..pos];
                    splits += 1;

                    // Stop if we've reached the maximum number of splits
                    if splits >= maxsplit {
                        break;
                    }
                }
                // Push the remaining part (or the whole string if no separator was found)
                parts.push(remaining.to_string());

                // Reverse the parts to maintain the right-split order
                parts.reverse();
                parts
            }
        })
        .collect()
}

fn main() {
    // Example usage
    let strings = vec!["one,two,three".to_string(), "four,five".to_string(), "".to_string()];
    let separator = ",".to_string();
    let max_splits = 1;

    let result = rsplit(strings, separator, max_splits);
    for res in result {
        println!("{:?}", res);
    }
}